    @Test
    void randomTypedSecureRandomWorksDuringConcurrentCollection() throws Exception {
        final Path project = project("secure-random-through-random-concurrent");
        writeJava(project, "com.acme.Main", """
            package com.acme;
            import java.security.SecureRandom;
            import java.util.Random;
            import java.util.concurrent.atomic.AtomicInteger;
            public final class Main {
                static final Random RANDOM = new SecureRandom();
                static final java.util.random.RandomGenerator GENERATOR = new SecureRandom();
                static final AtomicInteger errors = new AtomicInteger();
                static final class Custom implements java.util.random.RandomGenerator {
                    long value;
                    public long nextLong() { long result = value; value = value + 1; return result; }
                    public void nextBytes(byte[] bytes) { bytes[0] = 42; }
                    public int nextInt(int bound) { return bound + 42; }
                    public int nextInt() { return 41; }
                }
                static final class Worker implements Runnable {
                    public void run() {
                        java.util.random.RandomGenerator custom = new Custom();
                        for (int i = 0; i < 100; i++) {
                            byte[] bytes = new byte[64];
                            RANDOM.nextBytes(bytes);
                            int value = RANDOM.nextInt(5);
                            GENERATOR.nextBytes(bytes);
                            int other = GENERATOR.nextInt(5);
                            custom.nextBytes(bytes);
                            new String(new char[] {'x', 'y'});
                            if (bytes.length != 64 || bytes[0] != 42 || value < 0 || value >= 5 || other < 0 || other >= 5
                                || custom.nextLong() != i || custom.nextInt(5) != 47 || custom.nextInt() != 41) errors.incrementAndGet();
                        }
                    }
                }
                public static void main(String[] args) throws InterruptedException {
                    Thread first = new Thread(new Worker()); Thread second = new Thread(new Worker());
                    first.start(); second.start(); first.join(); second.join();
                    System.out.println(errors.get());
                }
            }
            """);
        final CliRun build = run(tempDir, "build", project.toString());
        assertThat(build.exitCode()).as(build.stderr()).isZero();
        final ProcessResult result = process(project,
            List.of(project.resolve(".javan/bin/secure-random-through-random-concurrent").toString()),
            Duration.ofSeconds(60), Map.of("JAVAN_GC_SAFEPOINT_INTERVAL", "1"));
        assertThat(result.exitCode()).as(result.stderr()).isZero();
        assertThat(result.stdout()).isEqualTo("0\n");
    }

